const inputData = $input.first().json;
const buttonText = inputData.message?.text || "";

const now = new Date();

const formatDate = (date) => {
  const d = String(date.getDate()).padStart(2, "0");
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const y = date.getFullYear();
  return `${d}.${m}.${y}`;
};

const today = formatDate(now);

const weekStart = new Date(now);
weekStart.setDate(now.getDate() - 6);

const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);

let period = "";
let dateFrom = "";
let dateTo = "";

switch (buttonText) {

  case "📅 Сегодня":
    period = "today";
    dateFrom = today;
    dateTo = today;
    break;

  case "📅 Неделя":
    period = "week";
    dateFrom = formatDate(weekStart);
    dateTo = today;
    break;

  case "📅 Месяц":
    period = "month";
    dateFrom = formatDate(monthStart);
    dateTo = today;
    break;

  default:
    period = "all";
    dateFrom = "";
    dateTo = "";
}

return [{
  json: {
    ...inputData,
    period,
    dateFrom,
    dateTo
  }
}];

const transactions = $input.all();

// Период ("Неделя" или "Месяц")
const period = $('Switch').first().json.message.text.toLowerCase();

const now = new Date();
const startDate = new Date(now);

if (period.includes("нед")) {
  startDate.setDate(now.getDate() - 7);
} else {
  startDate.setMonth(now.getMonth() - 1);
}

let income = 0;
let expense = 0;

const expenseCategories = {};
const incomeCategories = {};

for (const item of transactions) {

  const row = item.json;

  // ---------- ДАТА ----------
  let rowDate;

  if (row.Date.includes(".")) {
    const [day, month, year] = row.Date.split(".");
    rowDate = new Date(`${year}-${month}-${day}`);
  } else {
    rowDate = new Date(row.Date);
  }

  if (rowDate < startDate) continue;

  // ---------- ДАННЫЕ ----------
  const type = String(row.Type || "").trim().toLowerCase();
  const amount = Number(row.Amount) || 0;
  const category = row.Category || "Без категории";

  if (type === "доход") {

    income += amount;

    incomeCategories[category] =
      (incomeCategories[category] || 0) + amount;

  }

  if (type === "расход") {

    expense += amount;

    expenseCategories[category] =
      (expenseCategories[category] || 0) + amount;

  }

}

const balance = income - expense;

const topExpense =
Object.entries(expenseCategories)
.sort((a,b)=>b[1]-a[1])[0];

const topIncome =
Object.entries(incomeCategories)
.sort((a,b)=>b[1]-a[1])[0];

return [
{
json:{

income,
expense,
balance,

topExpenseCategory:
topExpense ? topExpense[0] : "Нет данных",

topExpenseAmount:
topExpense ? topExpense[1] : 0,

topIncomeCategory:
topIncome ? topIncome[0] : "Нет данных",

topIncomeAmount:
topIncome ? topIncome[1] : 0,

expenseCategories,
incomeCategories,

period

}
}
];

