// Получаем все входящие данные после Merge

const items = $input.all();

// ================================
// INPUT 1 — GOOGLE SHEETS
// ================================

const rows = items
  .filter(item => item.json.Date)
  .map(item => item.json);

// ================================
// INPUT 2 — ДАТЫ
// ================================

const dateData = items.find(
  item => item.json.dateFrom && item.json.dateTo
);

if (!dateData) {
  throw new Error("Не найдены даты из Code-ноды");
}

const dateFrom = dateData.json.dateFrom;
const dateTo = dateData.json.dateTo;

// ================================
// ФУНКЦИЯ ПАРСИНГА ДАТ
// ================================

function parseDate(value) {

  if (!value) return null;

  value = String(value).trim();

  // DD.MM.YYYY

  if (value.includes(".")) {

    const [day, month, year] = value.split(".");

    return new Date(
      Number(year),
      Number(month) - 1,
      Number(day)
    );
  }

  // YYYY-MM-DD

  if (value.includes("-")) {

    const [year, month, day] = value.split("-");

    return new Date(
      Number(year),
      Number(month) - 1,
      Number(day)
    );
  }

  return null;
}

// ================================
// ПЕРИОД ОТЧЁТА
// ================================

const from = parseDate(dateFrom);
const to = parseDate(dateTo);

// ================================
// ФИЛЬТР ОПЕРАЦИЙ
// ================================

const operations = rows.filter(row => {

  const rowDate = parseDate(row.Date);

  if (!rowDate) return false;

  return rowDate >= from && rowDate <= to;

});

// ================================
// ГРУППИРОВКА
// ================================

const incomes = {};
const expenses = {};

let totalIncome = 0;
let totalExpense = 0;

for (const row of operations) {

  const amount = Number(row.Amount) || 0;

  const category = row.Category || "Другое";

  const type = String(row.Type).toLowerCase();

  if (type === "доход") {

    incomes[category] =
      (incomes[category] || 0) + amount;

    totalIncome += amount;

  }

  if (type === "расход") {

    expenses[category] =
      (expenses[category] || 0) + amount;

    totalExpense += amount;

  }

}

// ================================
// СОЗДАНИЕ ТЕКСТА
// ================================

let report = "📊 Отчёт\n\n";

report += "📥 Доходы\n\n";

if (Object.keys(incomes).length) {

  for (const cat in incomes) {

    report += `💼 ${cat} — ${incomes[cat]} ₽\n`;

  }

} else {

  report += "Нет данных\n";

}

report += `\nИтого: ${totalIncome} ₽\n\n`;

report += "📤 Расходы\n\n";

if (Object.keys(expenses).length) {

  for (const cat in expenses) {

    report += `🛒 ${cat} — ${expenses[cat]} ₽\n`;

  }

} else {

  report += "Нет данных\n";

}

report += `\nИтого: ${totalExpense} ₽\n\n`;

const balance = totalIncome - totalExpense;

report += `💰 Баланс: ${balance} ₽`;

// ================================
// ВЫХОД
// ================================

return [
  {
    json: {
      report,
      dateFrom,
      dateTo,
      operations_found: operations.length
    }
  }
];
